153	        Rollup.Figures before = rollup.of(sheetId);
154	        Claim claim = new Claim(sheetId, personId, scaled(amount), claimDate, dueBy, noteOf(note), corrects,
155	                claims.lastListed(sheetId) + 1);
156	        claim.setTerms(terms);
157	        boolean late = periods.existsBySheetIdAndSoftClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(
158	                sheetId, dueBy, dueBy);
159	        if (late) {
160	            claim.markLateEntry();
161	        }
162	        claim.setRef(reference);
163	        String tagged = tagsOf(tags);
164	        claim.setTags(tagged);
165	        Claim added = claims.saveAndFlush(claim);
166	        added.logStatus(user, today, shownDue(sheet, added, person));
167	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_ADDED", user, person, added, added.getNumber())
168	                + (reference == null ? "" : " ref=" + reference) + (tagged == null ? "" : " tags=" + tagged));
169	        if (late) {
170	            audit.recordChangeOnCommit(sheetId, user, entry("LATE_ENTRY", user, person, added, null));
171	        }
172	        rollup.recordChanges(sheetId, user, before);
173	        return added;
174	    }
