278	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason, boolean judged,
279	            LocalDate on) {
280	        sheets.load(sheetId, user);
281	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
282	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
283	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
284	        refuseIfClosed(sheetId, claim.getDueBy());
285	        if (!claim.getStatus().canBecome(next)) {
286	            throw new ResponseStatusException(HttpStatus.CONFLICT,
287	                    "A " + claim.getStatus() + " claim cannot become " + next);
288	        }
289	        String action = switch (next) {
290	            case OPEN -> "open";
291	            case SETTLED -> "settle";
292	            case VOID -> "void";
293	            default -> null;
294	        };
295	        if (action != null && !sheet.allows(action, roles.roleOf(sheetId, user))) {
296	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
297	        }
298	        if (next == ClaimStatus.DRAFT && !sheet.getToday().equals(claim.deletedOn())) {
299	            throw new ResponseStatusException(HttpStatus.CONFLICT,
300	                    "A deleted claim can be restored only on the day it was deleted");
301	        }
302	        boolean voidsSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
303	        if (voidsSettled) {
304	            refuseSettledVoid(sheet, user, claim);
305	        }
306	        String voidReason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, reason) : null;
307	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheet.getToday())) {
308	            throw new ResponseStatusException(HttpStatus.CONFLICT,
309	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
310	        }
311	        if (judged && next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) {
312	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
313	                    "The user who opened or last edited a claim cannot settle it");
314	        }
315	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
316	        LocalDate settledOn = next == ClaimStatus.SETTLED ? on : null;
317	        BigDecimal due = settledOn != null ? dueAsOf(sheet, claim, settledOn) : dueNow(sheet, claim, person);
318	        if (next == ClaimStatus.SETTLED) {
319	            if (judged) {
320	                refuseUnproven(sheet, claim, person, due);
321	            }
322	        } else if (next == ClaimStatus.OPEN) {
323	            refuseUnnoted(sheet, claim, due);
324	            refuseOverCap(sheetId, claim);
325	            refuseFlagged(sheet, user, person);
326	        }
327	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheet, user, person, due)) {
328	            next = ClaimStatus.PENDING;
329	        }
330	        if (next == ClaimStatus.OPEN && overReviewThreshold(sheet, claim, due)) {
331	            next = ClaimStatus.REVIEW;
332	        }
333	        Rollup.Figures before = rollup.of(sheetId);
334	        String number = claim.getNumber();
335	        claim.setStatus(next);
336	        if (next == ClaimStatus.REVIEW) {
337	            claim.setOpenedBy(user);
338	        } else if (next == ClaimStatus.OPEN) {
339	            number = nextNumber(sheet, claim.getDueBy());
340	            claim.setNumber(number);
341	            claim.setOpenedBy(user);
342	        } else if (next == ClaimStatus.SETTLED) {
343	            claim.setSettledDue(due);
344	        } else if (next == ClaimStatus.VOID) {
345	            claim.setVoidReason(voidReason);
346	        }
347	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
348	        Claim changed = claims.saveAndFlush(claim);
349	        String event = switch (next) {
350	            case OPEN -> "CLAIM_OPENED";
351	            case PENDING -> "CLAIM_PENDING";
352	            case SETTLED -> "CLAIM_SETTLED";
353	            case VOID -> "CLAIM_VOIDED";
354	            case DELETED -> "CLAIM_DELETED";
355	            case DRAFT -> "CLAIM_RESTORED";
356	            case REVIEW -> "CLAIM_REVIEW";
357	        };
358	        String line = entry(event, user, person, changed, number);
359	        if (next == ClaimStatus.SETTLED) {
360	            line += " due=" + dueText(changed);
361	            if (settledOn != null) {
362	                line += " on=" + settledOn;
363	            }
364	        } else if (voidsSettled) {
365	            line += " reversed=" + dueText(changed);
366	        }
367	        if (voidReason != null) {
368	            line += " reason=" + voidReason;
369	        }
370	        audit.recordChangeOnCommit(sheetId, user, line);
371	        if (next == ClaimStatus.SETTLED) {
372	            watches.notifyWatchers(sheetId, user, person, number);
373	        }
374	        rollup.recordChanges(sheetId, user, before);
375	        return changed;
376	    }
