378	    /** Settle every claim given, one at a time in the order given, by exactly the rules of settling one claim (a
379	     *  claim a clerk's limit makes PENDING counts as settled), as the sheet's next settle batch, each keeping its
380	     *  number; after the claims' own lines BATCH_SETTLED is recorded with the batch's count and the frozen figures
381	     *  of those SETTLED added up. All or nothing: when any claim cannot be settled, none is, nothing is written and
382	     *  null is returned. The claims, as saved, in the order given; none when none is given. */
383	    @Transactional
384	    public List<Claim> settleBatch(String sheetId, String user, List<Long> ids) {
385	        if (ids.isEmpty()) {
386	            return List.of();
387	        }
388	        for (long id : ids) {
389	            try {
390	                changeStatus(sheetId, user, id, ClaimStatus.SETTLED);
391	            } catch (ResponseStatusException refusal) {
392	                TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
393	                return null;
394	            }
395	        }
396	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
397	        int batch = sheet.nextSettleBatch();
398	        sheetStore.saveAndFlush(sheet);
399	        List<Claim> marked = ids.stream().map(id -> {
400	            Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
401	            claim.setSettleBatch(batch);
402	            return claims.saveAndFlush(claim);
403	        }).toList();
404	        BigDecimal total = marked.stream()
405	                .filter(claim -> claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null)
406	                .map(Claim::getSettledDue)
407	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
408	        audit.recordChangeOnCommit(sheetId, user, "BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
409	                + " count=" + marked.size() + " total=" + total.toPlainString());
410	        return marked;
411	    }
