588	    /** Write a reminder for an OPEN or PENDING claim, dated the sheet's today. Refused for a claim in any other
589	     *  status and one already reminded on the sheet's today. */
590	    @Transactional
591	    public Claim remind(String sheetId, String user, long id) {
592	        sheets.load(sheetId, user);
593	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
594	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
595	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
596	        if (!claim.getStatus().isOpen()) {
597	            throw new ResponseStatusException(HttpStatus.CONFLICT,
598	                    "A " + claim.getStatus() + " claim cannot be reminded; only an OPEN or PENDING one can");
599	        }
600	        if (sheet.getToday().equals(claim.getRemindedOn())) {
601	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today");
602	        }
603	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
604	        LocalDate previous = claim.getRemindedOn();
605	        boolean escalates = !claim.isEscalated() && sheet.getEscalateAfter() != null && previous != null
606	                && !previous.plusDays(sheet.getEscalateAfter()).isAfter(sheet.getToday());
607	        claim.remind(sheet.getToday());
608	        if (escalates) {
609	            claim.escalate();
610	        }
611	        Claim reminded = claims.saveAndFlush(claim);
612	        audit.recordChangeOnCommit(sheetId, user, entry("REMIND", user, person, reminded, reminded.getNumber()));
613	        if (escalates) {
614	            audit.recordChangeOnCommit(sheetId, user, entry("ESCALATE", user, person, reminded, reminded.getNumber()));
615	        }
616	        return reminded;
617	    }
618	
619	    /** Hold an OPEN or PENDING claim, or release it when held: while held it counts in no live due figure
620	     *  unless a statement binds it, as a held person's claims do, though it still counts in what is claimed. Refused for a claim in any other status. */
621	    @Transactional
622	    public Claim toggleHold(String sheetId, String user, long id) {
623	        sheets.load(sheetId, user);
624	        sheetStore.findLockedById(sheetId).orElseThrow();
625	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
626	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
627	        if (!claim.getStatus().isOpen()) {
628	            throw new ResponseStatusException(HttpStatus.CONFLICT,
629	                    "A " + claim.getStatus() + " claim cannot be held or released; only an OPEN or PENDING one can");
630	        }
631	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
632	        Rollup.Figures before = rollup.of(sheetId);
633	        claim.setHeld(!claim.isHeld());
634	        Claim saved = claims.saveAndFlush(claim);
635	        audit.recordChangeOnCommit(sheetId, user,
636	                entry(saved.isHeld() ? "CLAIM_HELD" : "CLAIM_RELEASED", user, person, saved, saved.getNumber()));
637	        rollup.recordChanges(sheetId, user, before);
638	        return saved;
639	    }
640	
641	    /** A steward waives an OPEN or PENDING claim's late charge: it bears none from then on, whatever its overdue
642	     *  state. Refused for anyone but a steward, a claim in any other status and a claim already waived. */
643	    @Transactional
644	    public Claim waive(String sheetId, String user, long id) {
645	        sheets.load(sheetId, user);
646	        sheetStore.findLockedById(sheetId).orElseThrow();
647	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
648	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
649	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
650	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward waives a claim's late charge");
651	        }
652	        if (!claim.getStatus().isOpen()) {
653	            throw new ResponseStatusException(HttpStatus.CONFLICT,
654	                    "A " + claim.getStatus() + " claim cannot be waived; only an OPEN or PENDING one can");
655	        }
656	        if (claim.isWaived()) {
657	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim's late charge was already waived");
658	        }
659	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
660	        claim.waive();
661	        Claim waived = claims.saveAndFlush(claim);
662	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_WAIVED", user, person, waived, waived.getNumber()));
663	        return waived;
664	    }
665	
666	    /** A steward approves a PENDING claim: it becomes SETTLED, its due fixed as it is at this moment (its bound figure, else its live
667	     *  one, with the late charge it has gained). Refused for a clerk, for the user who opened the claim or last edited it, for a
668	     *  claim that is not PENDING and for one due by inside a closed period. */
669	    @Transactional
670	    public Claim approve(String sheetId, String user, long id) {
