672	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
673	        Claim claim = pendingClaim(sheetId, user, id);
674	        if (claim.isOpenedOrEditedBy(user)) {
675	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
676	                    "The user who opened or last edited a claim cannot approve it");
677	        }
