871	        added.openAsSplit(nextNumber(sheet, dueBy), user, original.getNumber());
872	        added.setTags(original.getTags());
873	        if (original.isLateEntry()) {
874	            added.markLateEntry();
875	        }
876	        added.logStatus(user, sheet.getToday(), shownDue(sheet, added, person));
877	        added = claims.saveAndFlush(added);
878	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_SPLIT", user, person, original, original.getNumber())
879	                + " into=" + added.getNumber());
880	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_OPENED", user, person, added, added.getNumber()));
881	        rollup.recordChanges(sheetId, user, before);
882	        return new Split(original, added);
883	    }
