885	    /** Part-settle an OPEN claim: split the amount off it exactly as {@link #split} does, then settle the new claim
886	     *  exactly as {@link #changeStatus(String, String, long, ClaimStatus)} does (PENDING when the clerk limit says
887	     *  so), save that the four-eyes rules and the proof rule are judged on the original claim as it was before the
888	     *  split. A split or settle that would be refused refuses the whole action and nothing is written. The original,
889	     *  keeping the rest of its amount, and the new claim, as saved. */
890	    @Transactional
891	    public Split settlePart(String sheetId, String user, long id, BigDecimal amount) {
892	        sheets.load(sheetId, user);
893	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
894	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
895	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
896	        if (claim.getStatus() != ClaimStatus.OPEN) {
897	            throw new ResponseStatusException(HttpStatus.CONFLICT,
898	                    "A " + claim.getStatus() + " claim cannot be part-settled; only an OPEN one can");
899	        }
900	        if (claim.isOpenedOrEditedBy(user)) {
901	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
902	                    "The user who opened or last edited a claim cannot settle it");
903	        }
904	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
905	        refuseUnproven(sheet, claim, person, dueNow(sheet, claim, person));
906	        Split split = split(sheetId, user, id, amount);
907	        return new Split(split.original(),
908	                changeStatus(sheetId, user, split.split().getId(), ClaimStatus.SETTLED, null, false));
909	    }
