939	    /** The due a claim would have been settled at as it stood at the end of a date, that date standing in for the
940	     *  sheet's today, as the as-of view works it out: the sheet, its rates, the claim's person and its claims as they
941	     *  stood then (see {@link SheetHistory}), its bound figure, else its live one raised to the floor in force then,
942	     *  with the late charge it had gained on that figure by then on top; null when it had no figure. Refused for a date after the
943	     *  sheet's today and for a claim not on the sheet by then. */
944	    private BigDecimal dueAsOf(Sheet sheet, Claim claim, LocalDate on) {
945	        String sheetId = sheet.getId();
946	        if (on.isAfter(sheet.getToday())) {
947	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
948	                    "A claim can be settled as of a date on or before " + sheet.getToday());
949	        }
950	        SheetState then = history.asOf(sheetId, on).orElse(null);
951	        Claim claimThen = then == null ? null : then.rebuildClaims(sheetId).stream()
952	                .filter(c -> c.getId().equals(claim.getId())).findFirst().orElse(null);
953	        SheetState.PersonState personState = claimThen == null ? null
954	                : then.person(claimThen.getPersonId()).orElse(null);
955	        if (personState == null) {
956	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim was not on the sheet by " + on);
957	        }
958	        Sheet sheetThen = then.rebuildSheet(sheet, on);
959	        Person personThen = personState.rebuild(sheetId);
960	        List<Claim> claimsThen = then.rebuildClaims(sheetId);
961	        if (claimThen.getSettledDue() != null) {
962	            return claimThen.getSettledDue();
963	        }
964	        String grade = personThen.gradeOn(claimThen.getDate());
965	        BigDecimal figure = claimThen.isBound() ? claimThen.getBoundDue()
966	                : history.ratesOf(sheetId, then, on).inForceOn(grade, claimThen.getDate(), claimThen.getId())
967	                        .map(Rate::getRate)
968	                        .map(rate -> floored(claimThen, liveFigure(claimThen, rate,
969	                                sheetThen.roundingFor(roundingDate(claimThen, claimsThen))), sheetThen))
970	                        .orElse(null);
971	        return figure == null ? null : figure.add(lateCharge(claimThen, figure, sheetThen, grade));
972	    }
