978	        String sheetId = sheet.getId();
979	        return rates.of(sheetId).inForceOn(person.gradeOn(claim.getDate()), claim.getDate(), claim.getId())
980	                .map(Rate::getRate)
981	                .map(rate -> floored(claim, liveFigure(claim, rate, sheet.roundingFor(roundingDate(claim,
982	                        claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, claim.getPersonId())))), sheet))
983	                .orElse(null);
