1001	    /** The next number for a claim due by this day, opened now: within its period (<period name>-<n>, or X-<n>
1002	     *  in no period) while the sheet's period numbering is on by its today, else the next number in the sheet-wide
1003	     *  sequence its tree shares within the fiscal year of the day (FY<year>-<n>, counting from 1 each year). */
1004	    private String nextNumber(Sheet sheet, LocalDate date) {
1005	        if (!sheet.numbersPerPeriod()) {
1006	            int year = sheet.fiscalYearOf(date);
1007	            int last = lastNumberInTree(sheet, year);
1008	            ClaimFiscalSequence sequence = fiscalSequences.findBySheetIdAndFiscalYear(sheet.getId(), year)
1009	                    .orElseGet(() -> new ClaimFiscalSequence(sheet.getId(), year));
1010	            String number = sequence.nextAfter(last);
1011	            fiscalSequences.save(sequence);
1012	            return number;
1013	        }
1014	        String prefix = prefixOn(sheet, date);
1015	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
1016	                .orElseGet(() -> new ClaimSequence(sheet.getId(), prefix));
1017	        String number = sequence.next();
1018	        sequences.save(sequence);
1019	        return number;
1020	    }
