1022	    /** The last sheet-wide number given in a fiscal year anywhere in the sheet's tree but the sheet itself: the
1023	     *  sheet at the top of its line of parents and all of that sheet's descendants. The top sheet is locked so the
1024	     *  tree's numbers are given one at a time. */
1025	    private int lastNumberInTree(Sheet sheet, int fiscalYear) {
1026	        List<String> ancestors = sheetStore.ancestorsOf(sheet.getId(), Integer.MAX_VALUE);
1027	        String top = ancestors.isEmpty() ? sheet.getId() : ancestors.get(ancestors.size() - 1);
1028	        if (!top.equals(sheet.getId())) {
1029	            sheetStore.findLockedById(top);
1030	        }
1031	        Set<String> others = new HashSet<>(sheetStore.descendantsOf(top));
1032	        others.add(top);
1033	        others.remove(sheet.getId());
1034	        return others.isEmpty() ? 0 : fiscalSequences.lastNumberOf(others, fiscalYear);
1035	    }
