1043	    /** Refuse to settle or approve a claim whose due is above the proof threshold in force on its date for its
1044	     *  person's grade then while it has no proofs, or, while the sheet sets proof kinds, no proof of one of them (a
1045	     *  claim with no due, or with no threshold then, needs none). */
1046	    private static void refuseUnproven(Sheet sheet, Claim claim, Person person, BigDecimal due) {
1047	        BigDecimal threshold = sheet.proofThresholdFor(person.gradeOn(claim.getDate()), claim.getDate());
1048	        if (threshold == null || due == null || due.compareTo(threshold) <= 0) {
1049	            return;
1050	        }
1051	        if (claim.getProofs() == 0) {
1052	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
1053	                    "A claim whose due is above the proof threshold of " + threshold + " needs a proof first");
1054	        }
1055	        for (String kind : sheet.proofKindList()) {
1056	            if (claim.proofsOf(kind) == 0) {
1057	                throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
1058	                        "A claim whose due is above the proof threshold of " + threshold + " needs a " + kind + " proof first");
1059	            }
1060	        }
1061	    }
