1106	    /** Refuse a correction (a negative amount) that does not name, by number, a SETTLED claim of the same person,
1107	     *  or that exceeds what remains of it (its amount less the corrections already made against it, VOID and
1108	     *  DELETED ones and the claim {@code self} itself left out), and a claim that is not a correction but names one. */
1109	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects, Long self) {
1110	        if (amount.signum() >= 0) {
1111	            if (corrects != null) {
1112	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
1113	                        "Only a correction (a negative amount) names a claim it corrects");
1114	            }
1115	            return;
1116	        }
1117	        List<Claim> own = corrects == null ? List.of()
1118	                : claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, personId);
1119	        Claim target = own.stream()
1120	                .filter(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED)
1121	                .findFirst().orElse(null);
1122	        if (target == null) {
1123	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
1124	                    "A correction must name the number of a SETTLED claim of the same person");
1125	        }
1126	        BigDecimal remaining = own.stream()
1127	                .filter(c -> corrects.equals(c.getCorrects()) && !c.getId().equals(self)
1128	                        && c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
1129	                .map(Claim::getAmount).reduce(target.getAmount(), BigDecimal::add);
1130	        if (scaled(amount).negate().compareTo(remaining) > 0) {
1131	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
1132	                    "A correction may not exceed what remains of " + corrects + " (" + scaled(remaining).toPlainString() + ")");
1133	        }
1134	    }
