1193	     *  claim of the same person it corrects. */
1194	    public static LocalDate roundingDate(Claim claim, Collection<Claim> sheetClaims) {
1195	        if (claim.getCorrects() == null) {
1196	            return claim.getDate();
1197	        }
1198	        return sheetClaims.stream()
1199	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
