1215	    /** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure by the sheet's today: for each
1216	     *  full 30 days past its due-by plus its grade's grace days ({@code grade}: its person's grade in force on its
1217	     *  date), the late percent in force on that boundary date (that day plus 30, 60, 90 ... days) of the figure
1218	     *  plus the charges of the boundaries before it (compounding), rounded as the claim rounds, added up; 0.00 when not overdue, it has no figure, it is a correction or its late charge was waived. While a
1219	     *  statement binds the claim with a late charge, it is that charge, whatever the sheet's today. */
1220	    public static BigDecimal lateCharge(Claim claim, BigDecimal figure, Sheet sheet, String grade) {
1221	        BigDecimal none = BigDecimal.ZERO.setScale(2);
1222	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(sheet.getToday())) {
1223	            return none;
1224	        }
1225	        // A statement binds the late charge with the figure: while bound, it no longer follows the sheet's today.
1226	        if (claim.isBound() && claim.getBoundLate() != null && !claim.isCorrection() && !claim.isWaived()) {
1227	            return claim.getBoundLate();
1228	        }
1229	        return lateChargeAsOpen(claim, figure, sheet, grade);
1230	    }
