1232	    /** The late charge a claim would have gained on its figure by the sheet's today were it still open. */
1233	    private static BigDecimal lateChargeAsOpen(Claim claim, BigDecimal figure, Sheet sheet, String grade) {
1234	        BigDecimal none = BigDecimal.ZERO.setScale(2);
1235	        if (figure == null || claim.isCorrection() || claim.isWaived()) {
1236	            return none;
1237	        }
1238	        LocalDate from = overdueFrom(claim, sheet, grade);
1239	        long periods = ChronoUnit.DAYS.between(from, sheet.getToday()) / 30;
1240	        RoundingMode rounding = sheet.roundingFor(claim.getDate());
1241	        BigDecimal charge = none;
1242	        for (long k = 1; k <= periods; k++) {
1243	            charge = charge.add(dueOn(figure.add(charge), sheet.latePctOn(from.plusDays(30 * k)), rounding));
1244	        }
1245	        return charge;
1246	    }
