package net.officefloor.hq.app.claim;

import org.springframework.format.annotation.DateTimeFormat;
import net.officefloor.hq.app.history.SheetHistory;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** Claims on a sheet. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /**
     * A claim as the screen shows it; the amount is given with exactly two decimals, as is the due
     * fixed when it was settled (null while it is not settled, or if its grade had no rate then); openedBy
     * is who opened it (null while a draft); stated is whether its person's last statement binds it, to
     * statedDue (null if it had no figure then, when it stays n/a); corrects is the number of the claim a correction corrects (null
     * on any other claim); deferredUntil is the day it was deferred until (null if never deferred); log is its status log, oldest first;
     * proofs is how many proofs have been given for it; splitFrom is the number of the claim it was split off (null
     * on any other claim); lockedBy is who has its editor open, locking it for other users (null when no one has);
     * lateEntry is whether it was added while its period was soft-closed; remindedOn is the last day a reminder was
     * written for it (null if never); tags are its tags, sorted (none when it has none); voidReason is the reason it
     * was voided with (null when it was voided without one, or is not void); comments are its comments, oldest
     * first; editedBy is who last edited it (null if no one has); batch is the number of the settle batch that
     * settled it (null when it was not settled by one); lines are its lines, in the order added; waived is whether
     * a steward waived its late charge; statedLate is the late charge its person's last statement binds with
     * statedDue (null when not bound, or bound with none, when its late charge follows the sheet's today);
     * proofReceipts and proofPhotos are how many of its proofs are of each kind; held is whether it is held.
     */
    public record ClaimView(long id, long personId, String amount, LocalDate date, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
            LocalDate dueBy, LocalDate deferredUntil, List<LogLine> log, int proofs, String splitFrom,
            String lockedBy, boolean lateEntry, LocalDate remindedOn, String ref, List<String> tags,
            String voidReason, List<CommentLine> comments, String editedBy, Integer batch, List<LineView> lines,
            boolean waived, String statedLate, int proofReceipts, int proofPhotos, boolean held) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getBoundDue() == null ? null : claim.getBoundDue().toPlainString(), claim.getCorrects(),
                    claim.getDueBy(), claim.getDeferredUntil(), claim.getLog().stream().map(LogLine::of).toList(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(),
                    claim.getRemindedOn(), claim.getRef(), claim.tagList(), claim.getVoidReason(),
                    claim.getComments().stream().map(CommentLine::of).toList(), claim.getEditedBy(),
                    claim.getSettleBatch(), claim.getLines().stream().map(LineView::of).toList(),
                    claim.isWaived(),
                    claim.getBoundLate() == null ? null : claim.getBoundLate().toPlainString(),
                    claim.getProofReceipts(), claim.getProofPhotos(), claim.isHeld());
        }
    }

    /** A line of a claim's status log: the status it took, by whom, on the sheet's today then, at the due it had
     *  then with exactly two decimals (null when it had none). */
    public record LogLine(ClaimStatus status, String by, LocalDate on, String due) {

        public static LogLine of(ClaimLogEntry entry) {
            return new LogLine(entry.getStatus(), entry.getBy(), entry.getOn(),
                    entry.getDue() == null ? null : entry.getDue().toPlainString());
        }
    }

    /** A comment on a claim: who wrote it, on the sheet's today then, and its text. */
    public record CommentLine(String by, LocalDate on, String text) {

        public static CommentLine of(ClaimComment comment) {
            return new CommentLine(comment.getBy(), comment.getOn(), comment.getText());
        }
    }

    /** A line of a claim: its label, its quantity and its unit amount with exactly two decimals. */
    public record LineView(String label, int qty, String unit) {

        public static LineView of(ClaimLine line) {
            return new LineView(line.getLabel(), line.getQty(), line.getUnit().toPlainString());
        }
    }

    /** A line to add to a claim: a label, a quantity and a unit amount; the service refuses what is out of range. */
    public record LineForm(@Size(max = 200) String label, @NotNull Integer qty,
            @NotNull @Digits(integer = 12, fraction = 2) BigDecimal unit) {
    }

    /** A comment to add to a claim; an empty one is refused. */
    public record CommentForm(@Size(max = 1000) String text) {
    }

    /** A claim's values as the form submits them; a missing date takes the sheet's today. A negative amount is a
     *  correction, which names in corrects the number of the claim it corrects. */
    public record ClaimForm(
            @NotNull @Digits(integer = 12, fraction = 2) BigDecimal amount,
            LocalDate date,
            @Size(max = 1000) String note,
            @Size(max = 120) String corrects,
            @Size(max = 120) String ref,
            @Size(max = 1000) String tags) {
    }

    /** The status a claim is to move to; a void gives its reason from the sheet's list (none when not given), a settle
     *  the date it is settled as of (none when not given: as it stands now). */
    public record StatusChange(@NotNull ClaimStatus status, @Size(max = 200) String reason,
            @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate on) {
    }

    /** Why a steward rejects a PENDING claim. */
    public record Rejection(@NotBlank @Size(max = 200) @Pattern(regexp = "\\S+( \\S+)*") String reason) {
    }

    /** The day an OPEN claim is to be deferred until. */
    public record Deferral(@NotNull LocalDate until) {
    }

    /** The new date of an OPEN or PENDING claim. */
    public record Redating(@NotNull LocalDate date) {
    }

    /** The person a claim is to move to. */
    public record Reassignment(@NotNull Long personId) {
    }

    /** The amount to split off an OPEN claim. */
    public record Split(@NotNull @Digits(integer = 12, fraction = 2) BigDecimal amount) {
    }

    /** What a split did: the claim split, keeping the rest of its amount, and the new claim split off it. */
    public record SplitView(ClaimView original, ClaimView split) {
    }

    /** The claims selected to be opened together. */
    public record BulkOpen(@NotNull @Size(max = 1000) List<@NotNull Long> ids) {
    }

    /** What a bulk open did: how many it opened and refused, and the claims it opened, in the order opened. */
    public record BulkOpenView(int opened, int refused, List<ClaimView> claims) {
    }

    /** The claims selected to be settled together. */
    public record BulkSettle(@NotNull @Size(max = 1000) List<@NotNull Long> ids) {
    }

    /** What a bulk settle did: how many it settled (a claim that went to PENDING counts) and refused, and the
     *  claims it settled, in the order settled; batch is the number of the settle batch it made (null when it settled
     *  none). */
    public record BulkSettleView(int settled, int refused, List<ClaimView> claims, Integer batch) {
    }

    /** The claims selected to be moved together, and the person they are to move to. */
    public record BulkReassign(@NotNull @Size(max = 1000) List<@NotNull Long> ids, @NotNull Long personId) {
    }

    /** What a bulk move did: how many it moved and refused, and the claims it moved, in the order moved. */
    public record BulkReassignView(int reassigned, int refused, List<ClaimView> claims) {
    }

    /** The claims selected to be re-dated together, and their new date. */
    public record BulkRedate(@NotNull @Size(max = 1000) List<@NotNull Long> ids, @NotNull LocalDate date) {
    }

    /** What a bulk re-date did: how many it re-dated and refused, and the claims it re-dated, in the order re-dated. */
    public record BulkRedateView(int redated, int refused, List<ClaimView> claims) {
    }

    /** The claims selected to be voided together, and the reason from the sheet's list (none when not given). */
    public record BulkVoid(@NotNull @Size(max = 1000) List<@NotNull Long> ids, @Size(max = 200) String reason) {
    }

    /** What a bulk void did: how many it voided and refused, and the claims it voided, in the order voided. */
    public record BulkVoidView(int voided, int refused, List<ClaimView> claims) {
    }

    private final ClaimService claims;
    private final RoleService roles;
    private final SheetService sheets;
    private final SheetHistory history;

    public ClaimController(ClaimService claims, RoleService roles, SheetService sheets, SheetHistory history) {
        this.sheets = sheets;
        this.history = history;
        this.claims = claims;
        this.roles = roles;
    }

    @GetMapping("/claims")
    public List<ClaimView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            return history.viewsAsOf(sheetId, asOf).claims();
        }
        return claims.list(sheetId).stream().map(ClaimView::of).toList();
    }

    @PostMapping("/people/{personId}/claims")
    public ClaimView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ClaimForm request) {
        return ClaimView.of(claims.add(sheetId, user, personId, request.amount(), request.date(), request.note(),
                request.corrects(), request.ref(), request.tags()));
    }

    @PutMapping("/claims/{id}")
    public ClaimView update(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ClaimForm request) {
        return ClaimView.of(claims.update(sheetId, user, id, request.amount(), request.date(), request.note(),
                request.corrects(), request.ref(), request.tags()));
    }

    /** The claim's timeline: the audit lines about it, newest first, as the file holds them. */
    @GetMapping("/claims/{id}/timeline")
    public List<String> timeline(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id) {
        return claims.timeline(sheetId, id);
    }

    /** Open the claim's editor, locking it for other users. */
    @PostMapping("/claims/{id}/lock")
    public ClaimView lock(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(claims.lock(sheetId, user, id));
    }

    /** Cancel the claim's editor, releasing the caller's lock. */
    @DeleteMapping("/claims/{id}/lock")
    public ClaimView unlock(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(claims.unlock(sheetId, user, id));
    }

    @PutMapping("/claims/{id}/status")
    public ClaimView changeStatus(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody StatusChange request) {
        return ClaimView.of(claims.changeStatus(sheetId, user, id, request.status(), request.reason(), request.on()));
    }

    @PutMapping("/claims/{id}/approve")
    public ClaimView approve(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(claims.approve(sheetId, user, id));
    }

    @PutMapping("/claims/{id}/review")
    public ClaimView review(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(claims.review(sheetId, user, id));
    }

    @PutMapping("/claims/{id}/reject")
    public ClaimView reject(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody Rejection request) {
        return ClaimView.of(claims.reject(sheetId, user, id, request.reason()));
    }

    @PutMapping("/claims/{id}/resettle")
    public ClaimView resettle(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(claims.resettle(sheetId, user, id));
    }

    @PutMapping("/claims/{id}/defer")
    public ClaimView defer(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody Deferral request) {
        return ClaimView.of(claims.defer(sheetId, user, id, request.until()));
    }

    @PutMapping("/claims/{id}/date")
    public ClaimView redate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody Redating request) {
        return ClaimView.of(claims.redate(sheetId, user, id, request.date()));
    }

    /** A proof as the screen gives it: its kind, receipt or photo; a missing one means a receipt, not chosen. */
    public record ProofAdding(@Pattern(regexp = "receipt|photo") String kind) {
    }

    @PostMapping("/claims/{id}/proofs")
    public ClaimView addProof(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody(required = false) ProofAdding request) {
        return ClaimView.of(claims.addProof(sheetId, user, id, request == null ? null : request.kind()));
    }

    @PostMapping("/claims/{id}/lines")
    public ClaimView addLine(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody LineForm request) {
        return ClaimView.of(claims.addLine(sheetId, user, id, request.label(), request.qty(), request.unit()));
    }

    @PostMapping("/claims/{id}/comments")
    public ClaimView comment(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody CommentForm request) {
        return ClaimView.of(claims.comment(sheetId, user, id, request.text()));
    }

    @PostMapping("/claims/{id}/reminders")
    public ClaimView remind(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(claims.remind(sheetId, user, id));
    }

    @PostMapping("/claims/{id}/waiver")
    public ClaimView waive(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(claims.waive(sheetId, user, id));
    }

    @PostMapping("/claims/{id}/hold")
    public ClaimView hold(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(claims.toggleHold(sheetId, user, id));
    }

    @PutMapping("/claims/{id}/person")
    public ClaimView reassign(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody Reassignment request) {
        return ClaimView.of(claims.reassign(sheetId, user, id, request.personId()));
    }

    @PostMapping("/claims/{id}/split")
    public SplitView split(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody Split request) {
        ClaimService.Split split = claims.split(sheetId, user, id, request.amount());
        return new SplitView(ClaimView.of(split.original()), ClaimView.of(split.split()));
    }

    /** Part-settle an OPEN claim: split the amount off it and settle the new claim at once. */
    @PostMapping("/claims/{id}/settle-part")
    public SplitView settlePart(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody Split request) {
        ClaimService.Split split = claims.settlePart(sheetId, user, id, request.amount());
        return new SplitView(ClaimView.of(split.original()), ClaimView.of(split.split()));
    }

    /**
     * Open each selected claim that can be opened, one at a time in list order (people in the order listed,
     * newest claim first within a person), so they are numbered in that order; each that cannot be opened, or is
     * not on the sheet, is refused and left as it is.
     */
    @PostMapping("/claims/bulk-open")
    public BulkOpenView bulkOpen(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkOpen request) {
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer's bulk action, or one on an archived sheet, goes through with nothing done: every selected
            // claim is refused.
            return new BulkOpenView(0, (int) request.ids().stream().distinct().count(), List.of());
        }
        List<Long> ordered = claims.inListOrder(sheetId, request.ids());
        int refused = (int) request.ids().stream().distinct().count() - ordered.size();
        List<ClaimView> opened = new ArrayList<>();
        for (long id : ordered) {
            try {
                opened.add(ClaimView.of(claims.changeStatus(sheetId, user, id, ClaimStatus.OPEN)));
            } catch (ResponseStatusException refusal) {
                refused++;
            }
        }
        return new BulkOpenView(opened.size(), refused, opened);
    }

    /**
     * Settle every selected claim, one at a time in list order (people in the order listed, newest claim first
     * within a person), by exactly the rules of settling one claim; a claim a clerk's limit makes PENDING counts as
     * settled. All or nothing: when any selected claim cannot be settled, or is not on the sheet, none is settled,
     * every one is refused and nothing is written. Those settled are the sheet's next settle batch.
     */
    @PostMapping("/claims/bulk-settle")
    public BulkSettleView bulkSettle(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkSettle request) {
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer's bulk action, or one on an archived sheet, goes through with nothing done: every selected
            // claim is refused.
            return new BulkSettleView(0, (int) request.ids().stream().distinct().count(), List.of(), null);
        }
        int selected = (int) request.ids().stream().distinct().count();
        List<Long> ordered = claims.inListOrder(sheetId, request.ids());
        List<Claim> settled = ordered.size() < selected ? null : claims.settleBatch(sheetId, user, ordered);
        if (settled == null) {
            // All or nothing: one selected claim that cannot be settled, or is not on the sheet, refuses them all.
            return new BulkSettleView(0, selected, List.of(), null);
        }
        List<ClaimView> batch = settled.stream().map(ClaimView::of).toList();
        return new BulkSettleView(batch.size(), 0, batch, batch.isEmpty() ? null : batch.get(0).batch());
    }

    /**
     * Move each selected claim to the person, one at a time in list order (people in the order listed, newest claim
     * first within a person), by exactly the rules of moving one claim. Each that cannot be moved, or is not on the
     * sheet, is refused and left as it is.
     */
    @PostMapping("/claims/bulk-reassign")
    public BulkReassignView bulkReassign(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkReassign request) {
        int selected = (int) request.ids().stream().distinct().count();
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer's bulk action, or one on an archived sheet, goes through with nothing done: every selected
            // claim is refused.
            return new BulkReassignView(0, selected, List.of());
        }
        List<Long> ordered = claims.inListOrder(sheetId, request.ids());
        int refused = selected - ordered.size();
        List<ClaimView> moved = new ArrayList<>();
        for (long id : ordered) {
            try {
                moved.add(ClaimView.of(claims.reassign(sheetId, user, id, request.personId(), true)));
            } catch (ResponseStatusException refusal) {
                refused++;
            }
        }
        return new BulkReassignView(moved.size(), refused, moved);
    }

    /**
     * Re-date each selected claim, one at a time in list order (people in the order listed, newest claim first
     * within a person), by exactly the rules of re-dating one claim. Each that cannot be re-dated, or is not on the
     * sheet, is refused and left as it is.
     */
    @PostMapping("/claims/bulk-redate")
    public BulkRedateView bulkRedate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkRedate request) {
        int selected = (int) request.ids().stream().distinct().count();
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer's bulk action, or one on an archived sheet, goes through with nothing done: every selected
            // claim is refused.
            return new BulkRedateView(0, selected, List.of());
        }
        List<Long> ordered = claims.inListOrder(sheetId, request.ids());
        int refused = selected - ordered.size();
        List<ClaimView> redated = new ArrayList<>();
        for (long id : ordered) {
            try {
                redated.add(ClaimView.of(claims.redate(sheetId, user, id, request.date())));
            } catch (ResponseStatusException refusal) {
                refused++;
            }
        }
        return new BulkRedateView(redated.size(), refused, redated);
    }

    /**
     * Void each selected claim with the reason, one at a time in list order (people in the order listed, newest claim
     * first within a person), by exactly the rules of voiding one claim. Each that cannot be voided, or is not on the
     * sheet, is refused and left as it is.
     */
    @PostMapping("/claims/bulk-void")
    public BulkVoidView bulkVoid(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkVoid request) {
        int selected = (int) request.ids().stream().distinct().count();
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer's bulk action, or one on an archived sheet, goes through with nothing done: every selected
            // claim is refused.
            return new BulkVoidView(0, selected, List.of());
        }
        List<Long> ordered = claims.inListOrder(sheetId, request.ids());
        int refused = selected - ordered.size();
        List<ClaimView> voided = new ArrayList<>();
        for (long id : ordered) {
