  duplicates(sheetId: string): Observable<string[]> {
    return this.http.get<string[]>(`${this.base(sheetId)}/duplicates`);
  }

  add(sheetId: string, personId: number, claim: ClaimForm): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/people/${personId}/claims`, claim);
  }

  /** Add a DRAFT claim for the person named `name`, dated the sheet's today; one not on the sheet is
   *  added first with grade A. Refused as a whole when the person or the claim is. */
  quickAdd(sheetId: string, name: string, amount: string): Observable<QuickAddView> {
    return this.http.post<QuickAddView>(`${this.base(sheetId)}/quick-add`, { name, amount });
  }

  /** Open a claim per line of name,amount,date,note, in order, for people already on the sheet, updating the
   *  newest matching draft instead of adding one; a note ending in " #<reference>" gives the claim that reference.
   *  Refused as a whole when any line is. */
  paste(sheetId: string, text: string): Observable<PasteView> {
    return this.http.post<PasteView>(`${this.base(sheetId)}/claims/paste`, { text });
  }

  update(sheetId: string, id: number, claim: ClaimForm): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}`, claim);
  }

  /** Open a draft's editor, locking it for other users until it is saved or cancelled or the sheet's today
   *  changes. Refused while another user has it open. */
  lock(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/lock`, null);
  }

  /** Cancel a claim's editor, releasing the lock it took. */
  unlock(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.delete<ClaimView>(`${this.base(sheetId)}/claims/${id}/lock`);
  }

  changeStatus(sheetId: string, id: number, status: ClaimStatus, reason?: string, on?: string): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/status`,
      { status, reason: reason ?? null, on: on ?? null });
  }

  /** Defer an OPEN claim until `until` (yyyy-mm-dd), a day after the sheet's today. */
  defer(sheetId: string, id: number, until: string): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/defer`, { until });
  }

  /** A steward re-dates an OPEN or PENDING claim to `date` (yyyy-mm-dd). */
  redate(sheetId: string, id: number, date: string): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/date`, { date });
  }

  /** Raise a claim's proofs count by one, of a kind (null: none chosen, a receipt); refused for a SETTLED or VOID
   *  claim. */
  addProof(sheetId: string, id: number, kind: ProofKind | null): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/proofs`, { kind });
  }

  /** Add a line to a DRAFT claim; refused for a claim that is not a DRAFT, in a closed period or locked by another
   *  user, and for a blank label, a quantity below 1 or a unit amount with more than two decimals. */
  addLine(sheetId: string, id: number, line: ClaimLine): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/lines`, line);
  }

  /** Comment on a claim as the signed-in user on the sheet's today; an empty comment is refused. */
  comment(sheetId: string, id: number, text: string): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/comments`, { text });
  }

  /** The claim's timeline: the audit lines about it, newest first, as the file holds them. */
  timeline(sheetId: string, id: number): Observable<string[]> {
    return this.http.get<string[]>(`${this.base(sheetId)}/claims/${id}/timeline`);
  }

  /** A steward waives an OPEN or PENDING claim's late charge; refused once it was waived. */
  waive(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/waiver`, {});
  }

  /** Hold an OPEN or PENDING claim, or release it when held. */
  toggleHold(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/hold`, {});
  }

  /** Write a reminder for an OPEN or PENDING claim, dated the sheet's today; refused once it was reminded today. */
  remind(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/reminders`, {});
  }

  /** A steward approves a PENDING claim: it is SETTLED, its due fixed as it is now. */
  approve(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/approve`, {});
  }

  /** A steward reviews a REVIEW claim: it is OPEN, with its number. */
  review(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/review`, {});
  }

  /** A steward re-settles a SETTLED claim: its due fixed again as it would be today as an open, unbound claim. */
  resettle(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/resettle`, {});
  }

  /** A steward rejects a PENDING claim with a reason: it is OPEN again. */
  reject(sheetId: string, id: number, reason: string): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/reject`, { reason });
  }

  /** A steward moves a DRAFT, OPEN or PENDING claim to another person: it keeps its number and date, is no
   *  longer bound by a statement, and is listed as that person's newest claim. */
  reassign(sheetId: string, id: number, personId: number): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/person`, { personId });
  }

  /** Split `amount` off an OPEN claim into a new OPEN claim of the same person, date and note. */
  split(sheetId: string, id: number, amount: string): Observable<SplitView> {
    return this.http.post<SplitView>(`${this.base(sheetId)}/claims/${id}/split`, { amount });
  }

  /** Part-settle an OPEN claim: split `amount` off it and settle the new claim at once (PENDING when the clerk
   *  limit says so). */
  settlePart(sheetId: string, id: number, amount: string): Observable<SplitView> {
    return this.http.post<SplitView>(`${this.base(sheetId)}/claims/${id}/settle-part`, { amount });
  }

  /** Open each of the claims that can be opened, numbered in list order; the rest are refused and left as they are. */
  bulkOpen(sheetId: string, ids: readonly number[]): Observable<BulkOpenView> {
    return this.http.post<BulkOpenView>(`${this.base(sheetId)}/claims/bulk-open`, { ids });
  }

  /** Settle each of the claims that can be settled, in list order, as a single settle would; the rest are refused
   *  and left as they are. */
  bulkSettle(sheetId: string, ids: readonly number[]): Observable<BulkSettleView> {
    return this.http.post<BulkSettleView>(`${this.base(sheetId)}/claims/bulk-settle`, { ids });
  }

  /** Move each of the claims to the person, in list order, as a single move would; the rest are refused and left
   *  as they are. */
  bulkReassign(sheetId: string, ids: readonly number[], personId: number): Observable<BulkReassignView> {
    return this.http.post<BulkReassignView>(`${this.base(sheetId)}/claims/bulk-reassign`, { ids, personId });
  }

  /** Re-date each of the claims to `date` (yyyy-mm-dd), in list order, as a single re-date would; the rest are
   *  refused and left as they are. */
  bulkRedate(sheetId: string, ids: readonly number[], date: string): Observable<BulkRedateView> {
    return this.http.post<BulkRedateView>(`${this.base(sheetId)}/claims/bulk-redate`, { ids, date });
  }

  bulkVoid(sheetId: string, ids: readonly number[], reason: string | null): Observable<BulkVoidView> {
    return this.http.post<BulkVoidView>(`${this.base(sheetId)}/claims/bulk-void`, { ids, reason });
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }
}

