66:  /** The reason a steward flagged the person for, while the sheet's today is on or before its until-date; null or
67:   *  missing otherwise. */
68:  flag?: string | null;
69:  /** The user who may approve or reject the person's PENDING claims as a steward may; null or missing when none. */
70:  approver?: string | null;
71:}
72:
73:/** A past retirement: retired from `from`, unretired on `to` (yyyy-mm-dd). */
74:export interface RetirementView {
75:  from: string;
76:  to: string;
77:}
78:
79:export interface PersonForm {
80:  name: string;
81:  grade: Grade;
82:  /** The person's own terms in days; null: none. */
83:  terms: number | null;
84:  /** The person's contact; blank: none. */
85:  contact: string;
86:  /** The tags, comma separated (each trimmed and lower-cased by the store, repeats dropped); blank for none. */
87:  tags: string;
88:}
89:
90:/** An edit of a person: the grade is recorded from `gradeFrom` (yyyy-mm-dd; null takes the sheet's today). */
91:export interface PersonEdit extends PersonForm {
92:  gradeFrom: string | null;
93:  /** The date the terms are recorded from (yyyy-mm-dd), keeping those from other dates; null: from the beginning
94:   *  of time. */
95:  termsFrom: string | null;
96:}
97:
98:/** What a bulk grade did: how many people it changed, and those people as saved. */
99:export interface BulkGradeView {
100:  changed: number;
101:  people: PersonView[];
102:}
103:
104:/** What a bulk retire did: how many people it retired, and those people as saved. */
105:export interface BulkRetireView {
106:  retired: number;
107:  people: PersonView[];
108:}
109:
110:/** What an import did: how many people it added and updated, and those people, in line order. */
111:export interface ImportView {
112:  added: number;
113:  updated: number;
114:  people: PersonView[];
115:}
116:
117:/** The person's grade in force on `date` (yyyy-mm-dd): the one with the latest from-date on or before it. */
118:export function gradeOn(p: Pick<PersonView, 'grade' | 'grades'>, date: string): Grade {
119:  let inForce: GradeFrom | undefined;
120:  for (const g of p.grades) {
121:    if ((g.from === null || g.from <= date) && (inForce === undefined || (inForce.from ?? '') <= (g.from ?? ''))) inForce = g;
122:  }
123:  return inForce?.grade ?? p.grade;
124:}
125:
126:/** How the screen shows a person's name: the name, then their grade in force on `date` (yyyy-mm-dd). */
127:export function nameWithGrade(p: Pick<PersonView, 'name' | 'grade' | 'grades'>, date: string): string {
128:  return `${p.name} (${gradeOn(p, date)})`;
129:}
130:
131:// The people kept on a sheet, listed in their positions; new people go to the end.
132:@Injectable({ providedIn: 'root' })
133:export class People {
134:  private readonly http = inject(HttpClient);
135:  /** Whether retired people are listed: belongs to the screen, so loading a sheet leaves it as it is. */
136:  readonly showRetired = signal(false);
137:
138:  list(sheetId: string): Observable<PersonView[]> {
139:    return this.http.get<PersonView[]>(this.base(sheetId));
140:  }
141:
142:  add(sheetId: string, person: PersonForm): Observable<PersonView> {
143:    return this.http.post<PersonView>(this.base(sheetId), person);
144:  }
145:
146:  /** Add a person per pasted line of name,grade,terms,contact; when any line is refused, none is added. */
147:  importPeople(sheetId: string, text: string): Observable<ImportView> {
148:    return this.http.post<ImportView>(`${this.base(sheetId)}/import`, { text });
149:  }
150:
151:  /** Save an edit made from `version` of the person; refused (412) when someone has saved them since. */
152:  update(sheetId: string, id: number, version: number, person: PersonEdit): Observable<PersonView> {
153:    return this.http.put<PersonView>(`${this.base(sheetId)}/${id}`, { ...person, version });
154:  }
155:
156:  /** Retire the person from `from` (yyyy-mm-dd); null takes the sheet's today. */
157:  retire(sheetId: string, id: number, from: string | null): Observable<PersonView> {
158:    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/retire`, { from });
159:  }
160:
161:  /** Unretire a retired person on the sheet's today; refused (409) for anyone not retired. */
162:  unretire(sheetId: string, id: number): Observable<PersonView> {
163:    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/unretire`, {});
164:  }
165:
166:  /** Swap the person with the one above or below them: everyone on the sheet, in list order, as moved. */
167:  move(sheetId: string, id: number, direction: 'up' | 'down'): Observable<PersonView[]> {
168:    return this.http.post<PersonView[]>(`${this.base(sheetId)}/${id}/move`, { direction });
169:  }
170:
171:  /** Put the person on hold from `from` (null takes the sheet's today) to `to` (null: no end). */
172:  hold(sheetId: string, id: number, from: string | null, to: string | null): Observable<PersonView> {
173:    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/hold`, { from, to });
174:  }
175:
176:  /** A steward flags the person with a reason until a date (null takes the sheet's today). */
177:  flag(sheetId: string, id: number, reason: string, until: string | null): Observable<PersonView> {
178:    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/flag`, { reason, until });
179:  }
180:
181:  /** Set the person's approver (blank: none). */
182:  setApprover(sheetId: string, id: number, user: string): Observable<PersonView> {
183:    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/approver`, { user });
184:  }
185:
186:  /** Give the person an alias; refused when blank or already a name or alias on the sheet. */
187:  addAlias(sheetId: string, id: number, alias: string): Observable<PersonView> {
188:    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/aliases`, { alias });
189:  }
190:
191:  /** Merge the person into another (a steward only): the person merged into, as saved. */
192:  merge(sheetId: string, id: number, intoId: number): Observable<PersonView> {
193:    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/merge`, { intoId });
194:  }
195:
196:  /** Undo the transfer that brought the person here, on the day they arrived (a steward only). */
197:  undoTransfer(sheetId: string, id: number): Observable<void> {
198:    return this.http.post<void>(`${this.base(sheetId)}/${id}/transfer-undo`, {});
199:  }
200:
201:  /** Transfer the person to another sheet (a steward only); they leave this one. */
202:  transfer(sheetId: string, id: number, toSheetId: string): Observable<void> {
203:    return this.http.post<void>(`${this.base(sheetId)}/${id}/transfer`, { toSheetId });
204:  }
205:
206:  /** Give the selected people `grade` from `from` (yyyy-mm-dd; null takes the sheet's today), in list order. */
207:  bulkGrade(sheetId: string, ids: readonly number[], grade: Grade, from: string | null): Observable<BulkGradeView> {
208:    return this.http.post<BulkGradeView>(`${this.base(sheetId)}/bulk-grade`, { ids, grade, from });
209:  }
210:
211:  /** Retire the selected people from `from` (yyyy-mm-dd; null takes the sheet's today), in list order. */
212:  bulkRetire(sheetId: string, ids: readonly number[], from: string | null): Observable<BulkRetireView> {
213:    return this.http.post<BulkRetireView>(`${this.base(sheetId)}/bulk-retire`, { ids, from });
214:  }
215:
216:  private base(sheetId: string): string {
217:    return `/api/sheets/${encodeURIComponent(sheetId)}/people`;
218:  }
219:}

