700	  /** The person being flagged, so a second press waits for the first. */
701	  protected readonly flagging = signal<number | null>(null);
702	
703	  /** The person whose approver is being set, so a second press waits for the first. */
704	  protected readonly approving = signal<number | null>(null);
705	
706	  /** The person an alias is being added to, so a second press waits for the first. */
707	  protected readonly aliasing = signal<number | null>(null);
708	  /** The error of the last action taken on a person's row, until the next action on that row. */
709	  protected readonly personError = signal<{ id: number; message: string } | null>(null);
710	  private readonly claimsByPerson = computed(() => {
711	    const byPerson = new Map<number, ClaimView[]>();
712	    for (const c of this.claims()) byPerson.set(c.personId, [...(byPerson.get(c.personId) ?? []), c]);
713	    return byPerson;
714	  });
715	  /** For each person, the other people on the sheet their claims can be moved to. */
716	  private readonly othersByPerson = computed(() => {
717	    const people = this.people();
718	    return new Map(people.map((p) => [p.id, people.filter((q) => q.id !== p.id)]));
719	  });
720	  /** The sheet's today ('' before a sheet is loaded). */
721	  private readonly todayNow = computed(() => this.sheets.current()?.today ?? '');
722	  /** Whether each claim counts in the live totals: a deferred claim does not, nor do a person's open claims
723	   *  dated within one of their holds, or all of them once their retirement date is reached, when not bound by a
724	   *  statement. */
725	  private readonly countsNow = computed(() => {
726	    const today = this.todayNow();
727	    const byPerson = new Map(this.people().map((p) => [p.id, countsWithHolds(p.holds, today, p.retiredFrom)]));
728	    return (c: ClaimView) => (byPerson.get(c.personId) ?? countsWithHolds([], today))(c);
729	  });
730	  /** Whether each claim counts in what is claimed: as in the live totals, except that a hold does not take it out. */
