});
/** Per period: its due-total, as its row shows it, and its change from the period before it by start date (none
 *  for the earliest). */
protected readonly summaryByPeriod = computed<PeriodSummary[]>(() => {
  const due = this.dueByPeriod();
  const list = this.periods.list();
  const byStart = [...list].sort((a, b) => a.from.localeCompare(b.from) || a.id - b.id);
  const change = new Map(byStart.map((p, i) => [p.id, i === 0 ? ''
    : money(cents(due.get(p.id) ?? '0.00') - cents(due.get(byStart[i - 1].id) ?? '0.00'))]));
  return list.map((p) => ({ name: p.name, dueTotal: due.get(p.id) ?? '0.00', change: change.get(p.id) ?? '' }));
});
/** Per status: how many of the sheet's claims are in it. */
protected readonly summaryByStatus = computed<StatusSummary[]>(() => {
  const claims = this.claims();
  return SUMMARY_STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === status).length }));
});
/** How many of the sheet's claims are in a status. */
protected statusCount(status: string): number {
  return this.summaryByStatus().find((s) => s.status === status)?.count ?? 0;
}
/** How many of the sheet's claims are late for review on its today. */
protected readonly reviewLateCount = computed(() => {
  const sheet = this.sheets.current();
  if (sheet === null) return 0;
  return this.claims().filter((c) => isReviewLate(c, sheet.today, sheet.reviewSla)).length;
});
protected readonly voidReasons = inject(VoidReasons);
/** Per reason on the sheet's list, how many VOID claims were voided with it. */
protected readonly summaryByVoidReason = computed<VoidReasonSummary[]>(() => {
  const claims = this.claims();
  return this.voidReasons.all().map(({ reason }) => ({
    reason,
    count: claims.filter((c) => c.status === 'VOID' && c.voidReason === reason).length,
  }));
});
/** Each person's carried figure for each period, by person id then period id: the due of their claims that
 *  count which belong to a period ending before this one starts and were still OPEN or PENDING at the end of
 *  this period's last day, by the status log, plus their opening balance for it; a closed or soft-closed period keeps the figure fixed when it was
 *  closed. */
private readonly carriedByPersonPeriod = computed(() => {
  const periods = this.periods.list();
  const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
  const today = this.todayNow();
  const byPerson = new Map<number, Map<number, number>>();
  for (const p of this.people()) {
    const carried = new Map<number, number>();
    for (const pd of periods) {
      if (pd.closed || pd.softClosed) {
        carried.set(pd.id, cents(pd.closedPersonCarried?.[String(p.id)] ?? '0.00'));
        continue;
      }
      const counts = countsAtEndWithHolds(p.holds, today, pd.to, p.retiredFrom);
      let sum = cents(pd.personOpenings?.[String(p.id)] ?? '0.00');
      for (const c of this.claimsOf(p.id)) {
        const own = periodOn(periods, c.dueBy);
        const status = statusAt(c, pd.to);
        if (own && own.to < pd.from && (status === 'OPEN' || status === 'PENDING') && counts(c)) {
          sum += this.claimDue(p, c, dueTerms) ?? 0;
        }
      }
      carried.set(pd.id, sum);
    }
    byPerson.set(p.id, carried);
  }
  return byPerson;
});
/** A person's carried figure for a period, with two decimals. */
protected periodCarriedOf(personId: number, periodId: number): string {
  return money(this.carriedByPersonPeriod().get(personId)?.get(periodId) ?? 0);
}
/** A person's due-total for a period, with two decimals. */
protected periodDueOf(personId: number, periodId: number): string {
  return money(this.dueByPersonPeriod().get(personId)?.get(periodId) ?? 0);
}
protected readonly editingId = signal<number | null>(null);
/** The version of the person the editor loaded. */
private editingVersion = 0;
